package pe.edu.upeu.inscripcion.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.edu.upeu.inscripcion.dto.*;import pe.edu.upeu.inscripcion.repository.*;import pe.edu.upeu.inscripcion.client.CertificadoContextoClient;
@Service @RequiredArgsConstructor public class CertificadoDocumentoService {
 private final InscripcionService inscripciones;private final InscripcionRepository inscripcionRepo;private final CertificadoRepository certificados;private final CertificadoContextoClient contexto;
 @Transactional public CertificadoDocumento documento(Long id,String auth){contexto.propietario(inscripcionRepo.estudianteDe(id).orElseThrow(),auth);var i=inscripcionRepo.bloquear(id).orElseThrow();var c=inscripciones.certificado(id);if(c.fechaEmision()==null||!"DISPONIBLE".equals(c.estado())||!c.pagoConfirmado()||!inscripciones.estadoAcademico(id).elegibleCertificado()||i.getEstado()==pe.edu.upeu.inscripcion.entity.Inscripcion.EstadoInscripcion.REVOCADA||i.getEstado()==pe.edu.upeu.inscripcion.entity.Inscripcion.EstadoInscripcion.CANCELADA)throw new IllegalStateException("El certificado todavía no está disponible o perdió su vigencia");var entidad=certificados.findByInscripcionId(id).orElseThrow();if(entidad.getAlumnoNombre()==null||entidad.getCursoTitulo()==null){entidad.setAlumnoNombre(contexto.alumno(i.getEstudianteId(),auth));entidad.setCursoTitulo(contexto.curso(i.getCursoId()).titulo());certificados.save(entidad);}return new CertificadoDocumento(c.codigo(),entidad.getAlumnoNombre(),entidad.getCursoTitulo(),c.fechaEmision());}
}
